<?php require_once __DIR__.'/../bootstrap.php';require_admin();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)$_POST['id'];if(isset($_POST['delete']))$pdo->prepare('DELETE FROM users WHERE id=? AND is_admin=0')->execute([$id]);else $pdo->prepare('UPDATE users SET active=? WHERE id=?')->execute([isset($_POST['active'])?1:0,$id]);header('Location: users.php');exit;}$q=trim($_GET['q']??'');$s=$pdo->prepare('SELECT id,name,email,is_admin,active,created_at FROM users '.($q?'WHERE name LIKE ? OR email LIKE ? ':'').'ORDER BY id DESC LIMIT 100');$s->execute($q?["%$q%","%$q%"]:[]);$title='Users — AniRead';include __DIR__.'/../includes/header.php';?><h1>Users</h1><form class="filters"><input class="input" name="q" value="<?=e($q)?>" placeholder="Name or email"><button class="btn">Search</button></form><table class="table"><tr><th>Name</th><th>Email</th><th>Admin</th><th>Active</th><th></th></tr><?php foreach($s as $u):?><tr><td><?=e($u['name'])?></td><td><?=e($u['email'])?></td><td><?=$u['is_admin']?'Yes':'No'?></td><td><?=$u['active']?'Yes':'No'?></td><td><?php if(!$u['is_admin']):?><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=$u['id']?>"><button class="btn alt" name="active" value="1"><?=$u['active']?'Disable':'Enable'?></button><button class="btn alt" name="delete" data-confirm="Delete this user?">Delete</button></form><?php endif;?></td></tr><?php endforeach;?></table><?php include __DIR__.'/../includes/footer.php';
